<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('finance.export');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$scope=in_array($user['role_slug'],['psychologist','supervised'],true)?' AND (f.professional_id=:u OR p.primary_professional_id=:u2)':'';$pa=['t'=>$user['tenant_id'],'y'=>$year];if($scope)$pa+=['u'=>$user['id'],'u2'=>$user['id']];$st=db()->prepare("SELECT f.paid_at,f.description,f.amount,f.payer_document,p.name patient_name,p.cpf patient_cpf FROM financial_transactions f LEFT JOIN patients p ON p.id=f.patient_id AND p.tenant_id=f.tenant_id WHERE f.tenant_id=:t AND f.type='income' AND f.status='paid' AND YEAR(f.paid_at)=:y{$scope} ORDER BY f.paid_at");$st->execute($pa);$rows=$st->fetchAll();audit('finance.export_csv','financial_transaction',null,['year'=>$year,'count'=>count($rows)]);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="psicomanager-financeiro-'.$year.'.csv"');$o=fopen('php://output','wb');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Data','Pagador','CPF pagador','Descrição','Valor'],';', '"', '\\');foreach($rows as $r)fputcsv($o,[date('d/m/Y',strtotime($r['paid_at'])),$r['patient_name']??'',($r['payer_document']?:$r['patient_cpf']??''),$r['description'],number_format((float)$r['amount'],2,',','')],';','"','\\');fclose($o);exit;
